-- Filtering a view: the outer WHERE pushes into the definition
SELECT title, pct_done
FROM course_engagement
WHERE topic = 'frontend' AND enrollments >= 2;

-- Evolving a view without breaking consumers (dialects differ!)
-- PostgreSQL: atomic replace, name never disappears
-- CREATE OR REPLACE VIEW course_engagement AS <new definition>;
-- SQLite: no OR REPLACE — drop + recreate inside a transaction
BEGIN;
DROP VIEW IF EXISTS course_engagement;
CREATE VIEW course_engagement AS
SELECT c.id AS course_id, c.title, c.topic,
  COUNT(e.id) AS enrollments,
  COUNT(CASE WHEN e.completed = 1 THEN 1 END) AS completed,
  100.0 * COUNT(CASE WHEN e.completed = 1 THEN 1 END)
    / NULLIF(COUNT(e.id), 0) AS pct_done
FROM courses c
LEFT JOIN enrollments e ON e.course_id = c.id
GROUP BY c.id;
COMMIT;

DROP VIEW IF EXISTS course_engagement;
